HAND={1:("Transition to Module 2 &mdash; Direction",("Module 2 — Direction begins with Unit 2 — Strategy Visioning &amp; Success in Practice (SiP), where your group defines the strategy of the simulated company set out in its Problem Charter.","Module 2 — Direction begins with Unit 2 — Strategy Visioning &amp; Success in Practice (SiP), where each group defines the strategy of the simulated company set out in its Problem Charter.")),
2:("Transition to Unit 3 &mdash; SiP KISS Mapping &amp; OKR Definition",("Unit 3 translates your Success in Practice into the changes the organisation must make and the Objectives and Key Results that will measure its progress.","Unit 3 translates each group’s Success in Practice into the changes the organisation must make and the Objectives and Key Results that will measure its progress.")),
3:("Transition to Unit 4 &mdash; Direction Integrity (ABCV-MBT)",("Unit 4 tests whether the direction your OKRs express holds against customer reality, strategic boundaries, competition and the value you offer.","Unit 4 tests whether the direction each group’s OKRs express holds against customer reality, strategic boundaries, competition and the value the organisation offers.")),
4:("Transition to Module 3 &mdash; Influence","Module 3 — Influence begins with Unit 5 — Aligning Heart &amp; Mind, which prepares the people who carry this direction to understand, accept and adopt it."),
5:("Transition to Unit 6 &mdash; Performance Management Setup","Unit 6 builds the system that connects enterprise results to the contributions of people and the conditions the organisation provides."),
6:("Transition to Unit 7 &mdash; Establishing Performance Expectations",("Unit 7 turns the contributions on your Contribution Map into expectations their owners commit to.","Unit 7 turns the contributions on each group’s Contribution Map into expectations their owners commit to.")),
7:("Transition to Unit 8 &mdash; Performance Measurement","Unit 8 sets the review discipline that keeps these expectations visible and correctable during execution."),
8:("Transition to Unit 9 &mdash; Strategic Unclogging","Unit 9 addresses the blockages that remain when review shows execution has stalled."),
9:("Transition to Module 4 &mdash; Grounding","Module 4 — Grounding begins with Unit 10 — ESRG Alignment, which strengthens the organisational operating conditions that anchor performance."),
10:("Transition to Unit 11 &mdash; Culture Reinforcement &amp; Organisational Health","Unit 11 turns to the culture through which people perform, and the organisational health it produces."),
11:("Transition to Unit 12 &mdash; Sustaining Performance","Unit 12 brings ESRG alignment and organisational health together to sustain performance quarter by quarter.")}
U11LJ=[("1 · Awareness — What","Organisational values, culture and health; the Cultural Operating Code; the Five Observable Health Traits; the Organisational Health Pyramid."),("2 · Intelligence — Why","Organisational health as a performance multiplier; execution velocity; the price of poor health; health and sustained performance."),("3 · Extrapolating — Where","Organisational health signals and the thermometer; CXO functional bias and debiasing; personal health profile."),("4 · Integration — Collective","The Cross-CXO Health Architecture: the thermometer, functional scores, loss quantification and the enterprise position; from values to a Cultural Operating Code; individual reflection."),("5 · Application — In Practice","The Cross-CXO Organisational Health Clinic: functional assessments, consolidation, Review–Realign–Restore, the Organisational Health Response and the group’s Cultural Operating Code.")]
